def count_sccs(V, edges):
    adj = [[] for _ in range(V)]
    for u, v in edges:
        adj[u].append(v)

    disc = [-1] * V
    low = [-1] * V
    on_stack = [False] * V
    stack = []
    time = 0
    scc_count = 0

    def dfs(u):
        nonlocal time, scc_count
        disc[u] = low[u] = time
        time += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if disc[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            scc_count += 1
            while True:
                node = stack.pop()
                on_stack[node] = False
                if node == u:
                    break

    for i in range(V):
        if disc[i] == -1:
            dfs(i)
    return scc_count
